export const acquireSandbox = async (req: ClaimRequest): Promise<Sandbox> => {
  const existing = await findInstance({ "ai-agents:run-id": req.runId });
  if (existing) return existing;
  const group = `ai-agents-sandbox-${req.size}${req.spot ? "-spot" : ""}`;
  const before = await inServiceIds(group);
  await raiseDesiredByOne(group);
  for (;;) {
    heartbeat("waiting for a warm VM");
    for (const id of (await inServiceIds(group)).filter((i) => !before.includes(i))) {
      try {
        await detach(group, id);
      } catch (err) {
        if (err instanceof AutoScalingServiceException) continue;
        throw err;
      }
      await tagAsRun(id, req);
      return { instanceId: id, size: req.size, spot: req.spot, runId: req.runId };
    }
    await sleep(5_000);
  }
};

export const releaseSandbox = async (vm: Sandbox): Promise<void> => {
  await brokerInternal.delete(`/internal/runs/${vm.runId}`);
  await ec2.send(new TerminateInstancesCommand({ InstanceIds: [vm.instanceId] })).catch((err: Error) => {
    if (err.name !== "InvalidInstanceID.NotFound") throw err;
  });
};
